// Package postgres is the workspace module's Repo on the platform database (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/workspace"
)

// Repo implements workspace.Repo.
type Repo struct {
	q *Queries
}

var _ workspace.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{q: New(db)} }

// Create records that user owns ws.
func (r *Repo) Create(ctx context.Context, ws string, user int64, at time.Time) error {
	return r.q.InsertWorkspace(ctx, InsertWorkspaceParams{ID: ws, UserID: user, CreatedAt: at})
}

// Owner is the workspace's user, or workspace.ErrNotFound.
func (r *Repo) Owner(ctx context.Context, ws string) (int64, error) {
	id, err := r.q.WorkspaceOwner(ctx, ws)
	if errors.Is(err, sql.ErrNoRows) {
		return 0, workspace.ErrNotFound
	}
	return id, err
}
